  // Keep the same place in the world when hopping to/from the Nether.
  if (prev === 0 && next === -1) { view.x /= 8; view.z /= 8; }
  if (prev === -1 && next === 0) { view.x *= 8; view.z *= 8; }
  settings.dim = next;
  if (next !== 0 && settings.mode === '3d') setMode('relief');
  syncSegs();
